/* ---------- 30. PAYING FOR HEAT PROTECTION ---------- */
// How protection is paid for, delivered and kept going. Shown in Act on it, and in steps 3 and 4 of Plan a response.
// Draws on two Global Asia Insurance Partnership reports (2026), checked page by page. The parametric report did not evaluate
// consumer outcomes, contracts, pricing or trigger performance: use it for design questions, not as proof that a heat product works.
// cases: say who paid, who received, what it made possible, what it left out and whether it continued. Where sources disagree, say so.
// sections inside: fields saved with the plan, in step 3 · When heat reaches lenders: insights from a 2026 commentary, summarised in our words and attributed. Opinion, not a study. · ---------- 32. A WEEK IN THE HEAT ---------- · An exercise for funders, officials and NGOs: follow one worker’s money through a heatwave week, build protection, then test it. · The people are composites, not real individuals. Numbers are illustrative Indian rupees a day, and every one can be changed. · The tool only adds up cash. It never predicts illness, productivity or payouts, and never gives a score. · effect: hours = working hours recovered on hot days (an assumption, shown on the card); water = no need to buy water at work; · rentfree = no work cost on hot days; keepbonus = illness does not cost the attendance bonus; · people: protect = share of daily pay that heat cannot cut (a monthly wage); bonus = lost if ill; amounts = local payment sizes; · defaults = measures already in place by law; mtext = local names, descriptions and conditions for a measure. · rest = paid hours protected; freecare = no doctor fee; money = a payment (amount, arrival day); hospital = pays only if admitted. · conds: what has to be true for the person to actually use it. A measure counts only when every condition holds, · except a soft condition, which changes the cost but not whether it can be used. start: false means it starts unmet; auto: met by another measure.
